// Nodo “Function” de n8n
// Valida items[0].json.selection y retorna status con mensajes amistosos

const raw = items[0].json.selection;
const items_length = items[0].json.items_length;

// Usamos regex para validar que sea un número entero positivo sin signos ni símbolos
const validFormat = /^[0-9]+$/;

let result;

if (!validFormat.test(raw)) {
  // Tiene caracteres no permitidos (letras, signos, espacios, etc.)
  result = {
    status: 'error',
    message: `Ups, parece que tu elección “${raw}” contiene símbolos o no es un número válido. Por favor escribe un número del 1 al ${items_length} sin signos ni espacios.`
  };
} else {
  const sel = Number(raw);

  if (!Number.isInteger(sel)) {
    result = {
      status: 'error',
      message: `Veo que has ingresado ${raw}, pero necesitamos un número entero. Por favor elige un número sin decimales entre 1 y ${items_length}.`
    };
  } else if (sel < 1 || sel > items_length) {
    result = {
      status: 'error',
      message: `Tu selección es ${sel}, pero debe estar entre 1 y ${items_length}. Intenta de nuevo con un número dentro de ese rango.`
    };
  } else {
    result = {
      status: 'success',
      message: `¡Genial! Has seleccionado la opción número ${sel}.`,
      selection: sel
    };
  }
}

// Devolver resultado
return [{ json: result }];

